from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            a,b=y+dy,x+dx
                            if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==c:
                                seen.add((a,b)); q.append((a,b))
                cells.sort()
                ys=[y for y,x in cells]; xs=[x for y,x in cells]
                norm=[(y-min(ys),x-min(xs)) for y,x in cells]
                out.append((c,len(cells),tuple(sorted(norm)),min(ys),min(xs)))
    return out
