def allcomps(g):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for y in range(H):
        for x in range(W):
            if (y,x) in seen: continue
            col=g[y][x]; st=[(y,x)]; cells=[]
            seen.add((y,x))
            while st:
                cy,cx=st.pop(); cells.append((cy,cx))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W and (ny,nx) not in seen and g[ny][nx]==col:
                        seen.add((ny,nx)); st.append((ny,nx))
            my=min(c[0] for c in cells); mx=min(c[1] for c in cells)
            out.append((col,len(cells),tuple(sorted((c[0]-my,c[1]-mx) for c in cells)),my,mx))
    return out
