lib = '''"""Shared helpers for ARC grid tasks."""
from collections import defaultdict, deque


def components(grid):
    """4-connectivity components as (color, size, normshape, y, x)."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = []
    for y in range(h):
        for x in range(w):
            if seen[y][x]:
                continue
            col = grid[y][x]
            q = deque([(y, x)])
            seen[y][x] = True
            cells = []
            while q:
                cy, cx = q.popleft()
                cells.append((cy, cx))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = cy + dy, cx + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == col:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
            my, mx = min(ys), min(xs)
            shape = tuple(sorted((yy - my, xx - mx) for yy, xx in cells))
            out.append((col, len(cells), shape, my, mx))
    return out


def shape_counts(comps):
    """Map normalized shape -> list of components."""
    d = defaultdict(list)
    for c in comps:
        d[c[2]].append(c)
    return d


def find_l_bar(comps):
    """Return (color, cellset) of the unique thin L-bar component (both arms >=3)."""
    by_col = defaultdict(list)
    for c in comps:
        by_col[c[0]].append(c)
    for col, lst in by_col.items():
        if len(lst) != 1:
            continue
        col_, size, shape, y, x = lst[0]
        ys = [p[0] for p in shape]; xs = [p[1] for p in shape]
        hh, ww = max(ys) + 1, max(xs) + 1
        if hh >= 3 and ww >= 3 and size == hh + ww - 1:
            return col, {(y + a, x + b) for a, b in shape}
    return None


def recolor_farther_duplicate(grid):
    """Recolor the farther copy of the duplicate-shape pair nearest the L-bar to the bar color."""
    comps = components(grid)
    bar = find_l_bar(comps)
    if not bar:
        return grid
    bcol, barcells = bar
    bys = shape_counts(comps)
    h, w = len(grid), len(grid[0])
    best = None  # (dist, -size, pair)
    for shape, lst in bys.items():
        if len(lst) != 2:
            continue
        dists = []
        for c in lst:
            cells = {(c[3] + a, c[4] + b) for a, b in c[2]}
            dists.append(min(abs(a - by) + abs(b - bx) for a, b in cells for by, bx in barcells))
        dist = min(dists)
        key = (dist, -c[1])
        if best is None or key < best[0]:
            best = (key, lst, dists)
    if not best:
        return grid
    _, (c1, c2), (d1, d2) = best
    far = c1 if d1 > d2 else c2
    out = [row[:] for row in grid]
    for a, b in far[2]:
        out[far[3] + a][far[4] + b] = bcol
    return out
